-- Generated by scripts/build_metrics.py from data/pipeline/metrics.json. Don't edit;
-- change the JSON and rerun the script.
--
-- One macro per metric, so a query can use the site's own definition:
--   SELECT day, catch_rate(fraud_caught, fraud) FROM fraud_daily;
-- and fraud_metrics: every metric over fraud_totals, one row each.

-- Catch rate: Share of fraudulent orders the rules flagged (sent to review or declined).
CREATE OR REPLACE MACRO catch_rate(fraud_caught, fraud) AS CAST(fraud_caught AS DOUBLE) / nullif(fraud, 0);
-- Fraud approved: Share of fraudulent orders the rules approved: the fraud that got through.
CREATE OR REPLACE MACRO miss_rate(fraud, fraud_caught) AS CAST(fraud - fraud_caught AS DOUBLE) / nullif(fraud, 0);
-- Good customers declined: Share of legitimate orders the rules declined outright.
CREATE OR REPLACE MACRO false_decline_rate(false_declines, legit) AS CAST(false_declines AS DOUBLE) / nullif(legit, 0);
-- Good customers flagged: Share of legitimate orders the rules sent to review or declined.
CREATE OR REPLACE MACRO legit_flag_rate(flagged, fraud_caught, legit) AS CAST(flagged - fraud_caught AS DOUBLE) / nullif(legit, 0);
-- Fraud dollars stopped: Share of attempted fraud dollars on orders the rules flagged.
CREATE OR REPLACE MACRO dollars_stopped_share(fraud_dollars_stopped, fraud_dollars_approved) AS CAST(fraud_dollars_stopped AS DOUBLE) / nullif(fraud_dollars_stopped + fraud_dollars_approved, 0);
-- Fraud rate: Share of all checkouts that were fraudulent.
CREATE OR REPLACE MACRO fraud_rate(fraud, checkouts) AS CAST(fraud AS DOUBLE) / nullif(checkouts, 0);
-- Scoring timeouts: Share of checkouts whose fraud score timed out and failed open (approved unscored).
CREATE OR REPLACE MACRO timeout_rate(scoring_timeouts, checkouts) AS CAST(scoring_timeouts AS DOUBLE) / nullif(checkouts, 0);

CREATE OR REPLACE VIEW fraud_metrics AS
SELECT 'catch_rate' AS metric, 'Catch rate' AS label,
       'fraud_caught / fraud' AS definition,
       CAST(fraud_caught AS DOUBLE) AS numerator, CAST(fraud AS DOUBLE) AS denominator,
       catch_rate(fraud_caught, fraud) AS value
FROM fraud_totals
UNION ALL
SELECT 'miss_rate' AS metric, 'Fraud approved' AS label,
       '(fraud - fraud_caught) / fraud' AS definition,
       CAST(fraud - fraud_caught AS DOUBLE) AS numerator, CAST(fraud AS DOUBLE) AS denominator,
       miss_rate(fraud, fraud_caught) AS value
FROM fraud_totals
UNION ALL
SELECT 'false_decline_rate' AS metric, 'Good customers declined' AS label,
       'false_declines / legit' AS definition,
       CAST(false_declines AS DOUBLE) AS numerator, CAST(legit AS DOUBLE) AS denominator,
       false_decline_rate(false_declines, legit) AS value
FROM fraud_totals
UNION ALL
SELECT 'legit_flag_rate' AS metric, 'Good customers flagged' AS label,
       '(flagged - fraud_caught) / legit' AS definition,
       CAST(flagged - fraud_caught AS DOUBLE) AS numerator, CAST(legit AS DOUBLE) AS denominator,
       legit_flag_rate(flagged, fraud_caught, legit) AS value
FROM fraud_totals
UNION ALL
SELECT 'dollars_stopped_share' AS metric, 'Fraud dollars stopped' AS label,
       'fraud_dollars_stopped / (fraud_dollars_stopped + fraud_dollars_approved)' AS definition,
       CAST(fraud_dollars_stopped AS DOUBLE) AS numerator, CAST(fraud_dollars_stopped + fraud_dollars_approved AS DOUBLE) AS denominator,
       dollars_stopped_share(fraud_dollars_stopped, fraud_dollars_approved) AS value
FROM fraud_totals
UNION ALL
SELECT 'fraud_rate' AS metric, 'Fraud rate' AS label,
       'fraud / checkouts' AS definition,
       CAST(fraud AS DOUBLE) AS numerator, CAST(checkouts AS DOUBLE) AS denominator,
       fraud_rate(fraud, checkouts) AS value
FROM fraud_totals
UNION ALL
SELECT 'timeout_rate' AS metric, 'Scoring timeouts' AS label,
       'scoring_timeouts / checkouts' AS definition,
       CAST(scoring_timeouts AS DOUBLE) AS numerator, CAST(checkouts AS DOUBLE) AS denominator,
       timeout_rate(scoring_timeouts, checkouts) AS value
FROM fraud_totals;
